mapper.update:
UPDATE team
name = #{name}, description = #{description}, visibility = #{visibility}, avatar = #{avatar}, updated_at = NOW()
WHERE id = #{id}

mapper.select:
SELECT t.id AS id, t.name AS name, t.description AS description, t.visibility AS visibility, t.status AS status, t.owner_personnel_id AS ownerPersonnelId, (SELECT p.name FROM personnel p WHERE p.id = t.owner_personnel_id LIMIT 1) AS ownerName, (SELECT COUNT(*) FROM team_member m2 WHERE m2.team_id = t.id AND m2.deleted = 0) AS memberCount, DATE_FORMAT(t.created_at, '%Y-%m-%d %H:%i:%s') AS createdAt FROM team t WHERE t.deleted = 0
AND (t.name LIKE CONCAT('%', #{keyword}, '%') OR t.description LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY t.id DESC LIMIT #{offset}, #{limit}

SELECT r.id AS id, r.team_id AS teamId, r.personnel_id AS personnelId, p.name AS name, p.staff_id AS staffId, p.aro_user_id AS aroUserId, p.job_number AS jobNumber, p.department_name AS departmentName, p.project_group_name AS projectGroupName, r.type AS type, r.status AS status, r.message AS message, r.reviewer_personnel_id AS reviewerPersonnelId, DATE_FORMAT(r.created_at, '%Y-%m-%d %H:%i:%s') AS createdAt, DATE_FORMAT(r.reviewed_at, '%Y-%m-%d %H:%i:%s') AS reviewedAt FROM team_join_request r LEFT JOIN personnel p ON p.id = r.personnel_id WHERE r.team_id = #{teamId} AND r.deleted = 0
AND r.status = #{status}
ORDER BY r.id DESC LIMIT #{offset}, #{limit}

SELECT COUNT(1) FROM team_join_request r
WHERE r.team_id = #{teamId} AND r.deleted = 0

    AND r.status = #{status}
